CREATE TABLE roles (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE, label VARCHAR(80) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE permissions (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE role_permissions (role_id TINYINT UNSIGNED NOT NULL, permission_id SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(role_id, permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id)) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id TINYINT UNSIGNED NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, status ENUM('active','blocked','deleted') NOT NULL DEFAULT 'active', locale CHAR(2) NOT NULL DEFAULT 'nl', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(role_id) REFERENCES roles(id), INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED NULL, name VARCHAR(150) NOT NULL, slug VARCHAR(170) NOT NULL UNIQUE, description TEXT NULL, language CHAR(2) NOT NULL DEFAULT 'nl', visible TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL, INDEX(parent_id, visible)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE courses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NULL, title VARCHAR(180) NOT NULL, code VARCHAR(60) NOT NULL UNIQUE, description TEXT NULL, language CHAR(2) NOT NULL DEFAULT 'nl', status ENUM('draft','published','hidden','archived') NOT NULL DEFAULT 'draft', enrollment_mode ENUM('open','approval','code','invite') NOT NULL DEFAULT 'approval', access_code_hash VARCHAR(255) NULL, max_participants INT UNSIGNED NULL, starts_at DATETIME NULL, ends_at DATETIME NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id), INDEX(status, category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE course_trainers (course_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(course_id,user_id), FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE enrollments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, status ENUM('requested','approved','rejected','withdrawn') NOT NULL DEFAULT 'requested', requested_at DATETIME NOT NULL, decided_at DATETIME NULL, decided_by BIGINT UNSIGNED NULL, UNIQUE KEY uq_enrollment(course_id,user_id), FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(decided_by) REFERENCES users(id) ON DELETE SET NULL, INDEX(status,course_id)) ENGINE=InnoDB;
CREATE TABLE sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, position INT NOT NULL DEFAULT 0, visible TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE, INDEX(course_id, position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, section_id BIGINT UNSIGNED NOT NULL, type ENUM('page','link','file') NOT NULL DEFAULT 'page', title VARCHAR(180) NOT NULL, content MEDIUMTEXT NULL, url VARCHAR(2048) NULL, position INT NOT NULL DEFAULT 0, visible TINYINT(1) NOT NULL DEFAULT 1, completion_required TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(section_id) REFERENCES sections(id) ON DELETE CASCADE, INDEX(section_id, position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE activity_progress (activity_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, opened_at DATETIME NOT NULL, completed_at DATETIME NULL, PRIMARY KEY(activity_id,user_id), FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, ip_hash CHAR(64) NOT NULL, attempted_at DATETIME NOT NULL, INDEX(email,attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id BIGINT UNSIGNED NULL, ip_hash CHAR(64) NULL, metadata JSON NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX(created_at), INDEX(entity_type,entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
